/**
 * WIRE-5 — client ↔ host contract comparator (no browser, no host process).
 *
 * The client talks to the host through HAND-WRITTEN types (`PersonaRemote`, `PersonaReviewRemote`, `*Wire`, …) while the
 * host validates every Remote call against the STRICT zod schemas generated by Typert (`persona-host/lib/typert.host.js`).
 * Any drift (missing required key, key the host does not know, method that does not exist, literal that the schema refuses)
 * becomes a runtime `invalid-request` the user only sees as a dead button. This module finds the drift statically:
 *   1. every method signature of the hand-written remote interfaces vs the generated schema (names, keys, optionality, nested);
 *   2. every call site `x.<hostMethod>({ ... })` in the client: unknown keys, missing keys, literals the schema refuses.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'
import ts from 'typescript'
import { REPO_ROOT } from './paths.ts'

const CLIENT_SRC = join(REPO_ROOT, 'packages', 'persona', 'client-ui-persona', 'src', 'client')
const HOST_TYPES = join(REPO_ROOT, 'packages', 'persona', 'persona-host', 'src', 'types.ts')
const EVENTS_REPO = join(REPO_ROOT, 'packages', 'persona', 'persona-store', 'src', 'events', 'repos.ts')

/** Runtime page-size cap enforced by the store (`clampLimit`: 1..N) — the zod schema cannot see it. Read from source so it never drifts. */
function runtimeLimitMax(): number {
  try {
    const match = /limit\s*>\s*(\d+)/u.exec(readFileSync(EVENTS_REPO, 'utf8'))
    return match?.[1] === undefined ? 200 : Number(match[1])
  } catch {
    return 200
  }
}

/** Minimal view of a zod schema (v4) — only what we introspect. */
interface Zod {
  readonly def?: { readonly type?: string; readonly innerType?: Zod; readonly shape?: Readonly<Record<string, Zod>>; readonly element?: Zod; readonly options?: readonly Zod[] }
  readonly shape?: Readonly<Record<string, Zod>>
  safeParse(value: unknown): { success: boolean }
}

interface Invocation {
  readonly method: string
  readonly parameters: ReadonlyArray<{ readonly codec: { create(): Zod }; readonly strictCodec?: { create(): Zod } }>
}

export interface ShapeNode {
  readonly kind: 'object' | 'array' | 'other'
  readonly props?: ReadonlyMap<string, { readonly optional: boolean; readonly node: ShapeNode }>
  readonly element?: ShapeNode
}

export interface Finding {
  readonly where: string
  readonly method: string
  readonly problem: string
}

/** Load the generated Typert face: method name → strict parameter schema. */
export async function loadHostSchemas(): Promise<Map<string, Zod>> {
  const generated = await import(join(REPO_ROOT, 'packages', 'persona', 'persona-host', 'lib', 'typert.host.js')) as { TYPERT: { invocations: readonly Invocation[] } }
  const out = new Map<string, Zod>()
  for (const invocation of generated.TYPERT.invocations) {
    const param = invocation.parameters[0]
    if (param === undefined) continue
    out.set(invocation.method, (param.strictCodec ?? param.codec).create())
  }
  return out
}

function unwrap(schema: Zod): { schema: Zod; optional: boolean } {
  let current = schema
  let optional = false
  for (let i = 0; i < 12; i += 1) {
    const type = current.def?.type
    if ((type === 'optional' || type === 'default' || type === 'prefault') && current.def?.innerType !== undefined) { optional = true; current = current.def.innerType; continue }
    if ((type === 'readonly' || type === 'nullable' || type === 'lazy' || type === 'catch' || type === 'nonoptional') && current.def?.innerType !== undefined) { current = current.def.innerType; continue }
    if (type === 'union' && current.def?.options !== undefined) {
      const real = current.def.options.filter(option => option.def?.type !== 'literal' || (option as unknown as { def: { values?: readonly unknown[] } }).def.values?.[0] !== null)
      if (real.length === 1 && real[0] !== undefined) { current = real[0]; continue }
    }
    break
  }
  return { schema: current, optional }
}

/** zod → comparable key tree. */
export function shapeOfZod(schema: Zod, depth = 0): ShapeNode {
  const { schema: inner } = unwrap(schema)
  const type = inner.def?.type
  if (type === 'object' && depth < 5) {
    const shape = inner.def?.shape ?? inner.shape ?? {}
    const props = new Map<string, { optional: boolean; node: ShapeNode }>()
    for (const [key, value] of Object.entries(shape)) {
      const un = unwrap(value)
      props.set(key, { optional: un.optional, node: shapeOfZod(un.schema, depth + 1) })
    }
    return { kind: 'object', props }
  }
  if (type === 'array' && inner.def?.element !== undefined && depth < 5) return { kind: 'array', element: shapeOfZod(inner.def.element, depth + 1) }
  return { kind: 'other' }
}

interface Declared { readonly node: ts.Node; readonly source: ts.SourceFile }

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name)
    if (statSync(abs).isDirectory()) walk(abs, out)
    else if (/\.(ts|tsx)$/u.test(name) && !/\.(spec|test)\./u.test(name) && !name.endsWith('.d.ts')) out.push(abs)
  }
  return out
}

/** Index of interface / type alias declarations across the client and the host `types.ts`. */
function indexDeclarations(files: readonly string[]): Map<string, Declared[]> {
  const index = new Map<string, Declared[]>()
  for (const file of files) {
    const source = ts.createSourceFile(file, readFileSync(file, 'utf8'), ts.ScriptTarget.ES2022, true, file.endsWith('x') ? ts.ScriptKind.TSX : ts.ScriptKind.TS)
    const visit = (node: ts.Node): void => {
      if ((ts.isInterfaceDeclaration(node) || ts.isTypeAliasDeclaration(node))) {
        const list = index.get(node.name.text) ?? []
        list.push({ node, source })
        index.set(node.name.text, list)
      }
      ts.forEachChild(node, visit)
    }
    visit(source)
  }
  return index
}

function resolveTypeNode(type: ts.TypeNode | undefined, index: ReadonlyMap<string, Declared[]>, depth = 0, seen = new Set<string>()): ShapeNode {
  if (type === undefined || depth > 6) return { kind: 'other' }
  if (ts.isParenthesizedTypeNode(type)) return resolveTypeNode(type.type, index, depth, seen)
  if (ts.isTypeLiteralNode(type)) return objectFromMembers(type.members, [], index, depth, seen)
  if (ts.isArrayTypeNode(type)) return { kind: 'array', element: resolveTypeNode(type.elementType, index, depth + 1, seen) }
  if (ts.isTypeOperatorNode(type)) return resolveTypeNode(type.type, index, depth, seen)
  if (ts.isUnionTypeNode(type)) {
    const real = type.types.filter(item => !(ts.isLiteralTypeNode(item) && item.literal.kind === ts.SyntaxKind.NullKeyword) && item.kind !== ts.SyntaxKind.UndefinedKeyword)
    return real.length === 1 && real[0] !== undefined ? resolveTypeNode(real[0], index, depth, seen) : { kind: 'other' }
  }
  if (ts.isIntersectionTypeNode(type)) {
    const parts = type.types.map(item => resolveTypeNode(item, index, depth + 1, seen))
    const props = new Map<string, { optional: boolean; node: ShapeNode }>()
    for (const part of parts) for (const [key, value] of part.props ?? []) props.set(key, value)
    return { kind: 'object', props }
  }
  if (ts.isTypeReferenceNode(type)) return resolveNamed(type.typeName.getText(), type.typeArguments, index, depth, seen)
  return { kind: 'other' }
}

function resolveNamed(
  name: string,
  typeArguments: readonly ts.TypeNode[] | undefined,
  index: ReadonlyMap<string, Declared[]>,
  depth: number,
  seen: Set<string>,
): ShapeNode {
  if (name === 'Readonly' || name === 'Partial' || name === 'Required') return resolveTypeNode(typeArguments?.[0], index, depth + 1, seen)
  if (name === 'ReadonlyArray' || name === 'Array') return { kind: 'array', element: resolveTypeNode(typeArguments?.[0], index, depth + 1, seen) }
  if (name === 'Promise' || name === 'RemoteResult') return resolveTypeNode(typeArguments?.[0], index, depth, seen)
  if (name === 'Omit' || name === 'Pick' || name === 'Record') return { kind: 'other' }
  if (seen.has(name)) return { kind: 'other' }
  const declared = index.get(name)
  if (declared === undefined || declared.length === 0) return { kind: 'other' }
  const next = new Set(seen).add(name)
  const props = new Map<string, { optional: boolean; node: ShapeNode }>()
  for (const decl of declared) {
    if (ts.isInterfaceDeclaration(decl.node)) {
      for (const heritage of decl.node.heritageClauses ?? []) {
        for (const base of heritage.types) {
          const baseShape = resolveNamed(base.expression.getText(), base.typeArguments, index, depth + 1, next)
          for (const [key, value] of baseShape.props ?? []) props.set(key, value)
        }
      }
      const own = objectFromMembers(decl.node.members, [], index, depth, next)
      for (const [key, value] of own.props ?? []) props.set(key, value)
    } else if (ts.isTypeAliasDeclaration(decl.node)) {
      const aliased = resolveTypeNode(decl.node.type, index, depth + 1, next)
      if (aliased.kind !== 'object') return aliased
      for (const [key, value] of aliased.props ?? []) props.set(key, value)
    }
  }
  return { kind: 'object', props }
}

function objectFromMembers(
  members: ts.NodeArray<ts.TypeElement>,
  _unused: readonly string[],
  index: ReadonlyMap<string, Declared[]>,
  depth: number,
  seen: Set<string>,
): ShapeNode {
  const props = new Map<string, { optional: boolean; node: ShapeNode }>()
  for (const member of members) {
    if (!ts.isPropertySignature(member) || member.name === undefined) continue
    if (ts.isIdentifier(member.name) || ts.isStringLiteral(member.name)) {
      props.set(member.name.text, { optional: member.questionToken !== undefined, node: resolveTypeNode(member.type, index, depth + 1, seen) })
    }
  }
  return { kind: 'object', props }
}

function compareShapes(path: string, client: ShapeNode, host: ShapeNode, method: string, where: string, out: Finding[]): void {
  if (client.kind !== 'object' || host.kind !== 'object') {
    if (client.kind === 'array' && host.kind === 'array' && client.element !== undefined && host.element !== undefined) compareShapes(`${path}[]`, client.element, host.element, method, where, out)
    return
  }
  const clientProps = client.props ?? new Map()
  const hostProps = host.props ?? new Map()
  for (const [key, info] of clientProps) {
    const target = hostProps.get(key)
    if (target === undefined) {
      out.push({ where, method, problem: `${path}.${key}: o cliente envia/declara uma chave que o host NÃO conhece (schema estrito recusa: unrecognized_keys)` })
      continue
    }
    compareShapes(`${path}.${key}`, info.node, target.node, method, where, out)
  }
  for (const [key, info] of hostProps) {
    if (info.optional) continue
    const mine = clientProps.get(key)
    if (mine === undefined) out.push({ where, method, problem: `${path}.${key}: o host EXIGE esta chave e o tipo do cliente não a tem` })
    else if (mine.optional) out.push({ where, method, problem: `${path}.${key}: o host EXIGE (obrigatória) e o cliente a declara opcional` })
  }
}

/**
 * Hand-written remote interfaces vs generated schemas.
 * @param schemas - From {@link loadHostSchemas}.
 */
export function compareRemoteInterfaces(schemas: ReadonlyMap<string, Zod>): { findings: Finding[]; checked: number; unresolved: string[] } {
  const files = [...walk(CLIENT_SRC), HOST_TYPES]
  const index = indexDeclarations(files)
  const findings: Finding[] = []
  const unresolved: string[] = []
  let checked = 0
  for (const [name, declarations] of index) {
    if (!/(Remote|Wire)$|^PersonaRemote$|RemoteClient$/u.test(name)) continue
    for (const decl of declarations) {
      if (!ts.isInterfaceDeclaration(decl.node) && !ts.isTypeAliasDeclaration(decl.node)) continue
      const members: readonly ts.TypeElement[] = ts.isInterfaceDeclaration(decl.node)
        ? decl.node.members
        : ts.isTypeLiteralNode(decl.node.type) ? decl.node.type.members : []
      const where = `${name} (${relative(REPO_ROOT, decl.source.fileName).replace(/\\/gu, '/')})`
      for (const member of members) {
        let method = ''
        let parameter: ts.ParameterDeclaration | undefined
        if (ts.isMethodSignature(member) && ts.isIdentifier(member.name)) {
          method = member.name.text
          parameter = member.parameters[0]
        } else if (ts.isPropertySignature(member) && ts.isIdentifier(member.name) && member.type !== undefined && ts.isFunctionTypeNode(member.type)) {
          method = member.name.text
          parameter = member.type.parameters[0]
        } else continue
        const schema = schemas.get(method)
        if (schema === undefined) {
          // Not a host Remote at all (helpers like `ping`, stream hooks, UI stubs) is common: only flag names the client calls on a *Remote/*Wire face.
          if (/^(ping|followMessages|observe)$/u.test(method)) continue
          findings.push({ where, method, problem: 'método declarado no tipo do cliente NÃO existe no host (nenhum Remote com esse nome)' })
          continue
        }
        if (parameter === undefined) continue
        const clientShape = resolveTypeNode(parameter.type, index)
        const hostShape = shapeOfZod(schema)
        if (clientShape.kind !== 'object') { unresolved.push(`${name}.${method}`); continue }
        checked += 1
        compareShapes('request', clientShape, hostShape, method, where, findings)
      }
    }
  }
  return { findings, checked, unresolved }
}

/** Object literal (possibly nested in arrays / `.map(x => ({...}))`) vs the host shape: unknown keys + required keys (no spreads). */
function checkLiteral(
  path: string,
  expr: ts.Expression,
  shape: ShapeNode,
  report: (problem: string) => void,
  depth = 0,
): void {
  if (depth > 4) return
  if (ts.isParenthesizedExpression(expr)) { checkLiteral(path, expr.expression, shape, report, depth); return }
  if (ts.isAsExpression(expr) || ts.isSatisfiesExpression(expr)) { checkLiteral(path, expr.expression, shape, report, depth); return }
  if (ts.isArrayLiteralExpression(expr) && shape.kind === 'array' && shape.element !== undefined) {
    for (const item of expr.elements) if (!ts.isSpreadElement(item)) checkLiteral(`${path}[]`, item, shape.element, report, depth + 1)
    return
  }
  if (ts.isCallExpression(expr) && ts.isPropertyAccessExpression(expr.expression) && expr.expression.name.text === 'map' && shape.kind === 'array' && shape.element !== undefined) {
    const callback = expr.arguments[0]
    if (callback !== undefined && (ts.isArrowFunction(callback) || ts.isFunctionExpression(callback))) {
      const body = callback.body
      if (ts.isBlock(body)) {
        for (const statement of body.statements) if (ts.isReturnStatement(statement) && statement.expression !== undefined) checkLiteral(`${path}[]`, statement.expression, shape.element, report, depth + 1)
      } else {
        checkLiteral(`${path}[]`, body, shape.element, report, depth + 1)
      }
    }
    return
  }
  if (ts.isObjectLiteralExpression(expr) && shape.kind === 'object') {
    const props = shape.props ?? new Map()
    const present = new Set<string>()
    let spread = false
    for (const prop of expr.properties) {
      if (ts.isSpreadAssignment(prop)) { spread = true; continue }
      const key = ts.isShorthandPropertyAssignment(prop) ? prop.name.text : (ts.isPropertyAssignment(prop) && (ts.isIdentifier(prop.name) || ts.isStringLiteral(prop.name))) ? prop.name.text : undefined
      if (key === undefined) continue
      present.add(key)
      const target = props.get(key)
      if (target === undefined) { report(`${path}.${key}: chave desconhecida do host (unrecognized_keys)`); continue }
      if (ts.isPropertyAssignment(prop)) checkLiteral(`${path}.${key}`, prop.initializer, target.node, report, depth + 1)
    }
    if (!spread) for (const [key, info] of props) if (!info.optional && !present.has(key)) report(`${path}.${key}: obrigatória ausente`)
  }
}

/**
 * Call sites `x.<hostMethod>({ ... })` in the client: keys the host does not know, required keys missing, literals refused.
 * @param schemas - From {@link loadHostSchemas}.
 */
export function scanClientCallSites(schemas: ReadonlyMap<string, Zod>): { findings: Finding[]; calls: number } {
  const findings: Finding[] = []
  let calls = 0
  const COMMON = new Set(['workspaceId', 'projectId'])
  for (const file of walk(CLIENT_SRC)) {
    const text = readFileSync(file, 'utf8')
    if (!/[A-Za-z]\.(?:[a-z][A-Za-z]+)\(\s*\{/u.test(text)) continue
    const source = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true, file.endsWith('x') ? ts.ScriptKind.TSX : ts.ScriptKind.TS)
    const where = relative(REPO_ROOT, file).replace(/\\/gu, '/')
    const visit = (node: ts.Node): void => {
      if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
        const method = node.expression.name.text
        const schema = schemas.get(method)
        const arg = node.arguments[0]
        if (schema !== undefined && arg !== undefined && ts.isObjectLiteralExpression(arg)) {
          calls += 1
          const host = shapeOfZod(schema)
          const props = host.props ?? new Map()
          const present = new Set<string>()
          let hasSpread = false
          const line = source.getLineAndCharacterOfPosition(arg.getStart()).line + 1
          for (const prop of arg.properties) {
            if (ts.isSpreadAssignment(prop)) { hasSpread = true; continue }
            const key = ts.isShorthandPropertyAssignment(prop) ? prop.name.text : (ts.isPropertyAssignment(prop) && (ts.isIdentifier(prop.name) || ts.isStringLiteral(prop.name))) ? prop.name.text : undefined
            if (key === undefined) continue
            present.add(key)
            const target = props.get(key)
            if (target === undefined) {
              findings.push({ where: `${where}:${String(line)}`, method, problem: `chave "${key}" desconhecida do host (unrecognized_keys)` })
              continue
            }
            if (ts.isPropertyAssignment(prop) && target.node.kind !== 'other') {
              checkLiteral(key, prop.initializer, target.node, (problem) => { findings.push({ where: `${where}:${String(line)}`, method, problem }) })
            }
            if (ts.isPropertyAssignment(prop) && (ts.isNumericLiteral(prop.initializer) || ts.isStringLiteral(prop.initializer) || prop.initializer.kind === ts.SyntaxKind.TrueKeyword || prop.initializer.kind === ts.SyntaxKind.FalseKeyword)) {
              const literal = ts.isNumericLiteral(prop.initializer) ? Number(prop.initializer.text) : ts.isStringLiteral(prop.initializer) ? prop.initializer.text : prop.initializer.kind === ts.SyntaxKind.TrueKeyword
              if (key === 'limit' && typeof literal === 'number' && literal > runtimeLimitMax()) {
                findings.push({ where: `${where}:${String(line)}`, method, problem: `limit: ${String(literal)} excede o teto de runtime do host (1–${String(runtimeLimitMax())}, persona-store events/repos.ts clampLimit): o schema não vê, o host recusa com invalid-input` })
              }
              const field = ((schema.def?.shape ?? schema.shape ?? {}) as Record<string, Zod>)[key]
              if (field !== undefined && !field.safeParse(literal).success) {
                findings.push({ where: `${where}:${String(line)}`, method, problem: `${key}: ${JSON.stringify(literal)} é recusado pelo schema do host` })
              }
            }
          }
          for (const [key, info] of props) {
            if (info.optional || present.has(key)) continue
            if (hasSpread && COMMON.has(key)) continue
            if (hasSpread) continue
            findings.push({ where: `${where}:${String(line)}`, method, problem: `obrigatória ausente: "${key}"` })
          }
        }
      }
      ts.forEachChild(node, visit)
    }
    visit(source)
  }
  return { findings, calls }
}
